MATCH path = shortestPath((start:PlantItem {tag:'CHV-74-18'})-[:send_to*]->(end:PlantItem {tag:'TK-315-6'}))
WITH [n IN nodes(path) | CASE
  WHEN n:Equipment THEN {tag: n.tag, kind: labels(n)[-3]}
  WHEN n:BallValve OR n:GlobeValve OR n:CheckValve OR n:OperatedValve THEN {tag: coalesce(n.tag, n.piping_component_name), kind: 'Valve'}
  ELSE {tag: n.tag, kind: 'Other'}
END] AS items
UNWIND items AS it
RETURN it.tag AS tag, it.kind AS kind
ORDER BY ...

MATCH (v:PlantItem {tag:'V-460-1'})-[:send_to]->(n:PlantItem)
RETURN v.tag AS from, labels(n) AS item_labels, n.tag AS tag, n.piping_component_name AS piping_component_name
ORDER BY tag, piping_component_name;
